const { z } = require('zod');
const rateLimit = require('express-rate-limit');
const router = require('express').Router();
router.use(rateLimit({ windowMs: 60000, max: 20 }));
const Item = z.object({ name: z.string().max(80) });
router.post('/api/items', (req, res) => { const item = Item.parse(req.body); res.json(item); });
router.post('/api/verify', (req, res) => res.json({ ok: true }));
module.exports = router;
